"""Narrative presentation: benefits, interactive product evidence, honest next step."""
import json,re
from html import escape as E
from urllib.parse import urlencode
from marketing_copy import MARKETING

def render_campaign(code,document,c,t,labels,phone,icon,assets):
    m=MARKETING[code]
    def extract(id):
        match=re.search(r'<section\b[^>]*id="'+id+r'"[^>]*>.*?</section>',document,re.S)
        if not match:raise ValueError('Missing section '+id)
        return match.group()
    country_section=extract('europe')
    gallery_section=extract('preview')
    service_section=extract('onroad')
    mail='mailto:support@rawlo.eu?'+urlencode({'subject':'RAWLO — '+m['early'],'body':m['early']+'.\n\n'+code.upper()})
    button=f'<a class="button" href="{E(mail,quote=True)}">{E(m["early"])}{icon("arrow")}</a>'
    steps=[('planner','itinerary','plan','planbody'),('navigation','navigation','drive','navbody'),('map','map','discover','mapbody'),('community','community','connect','communitybody')]
    tabs=''.join(f'<button type="button" role="tab" id="tour-tab-{i}" aria-controls="tour-panel" aria-selected="{"true" if i==0 else "false"}" tabindex="{0 if i==0 else -1}" data-tour-index="{i}"><span>0{i+1}</span>{icon(name)}<strong>{E(m[key])}</strong></button>' for i,(name,image,key,body) in enumerate(steps))
    data=[{'name':labels[name],'title':m[key],'body':c[body],'image':assets+image+'.png'} for name,image,key,body in steps]
    route_art='''<svg class="demo-route" viewBox="0 0 650 400" aria-hidden="true"><defs><pattern id="grid-pattern" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0v45" fill="none" stroke="#d4dedc" stroke-width=".7"/></pattern></defs><rect width="650" height="400" fill="url(#grid-pattern)"/><path class="terrain terrain-a" d="M0 320Q85 260 150 292T310 350T510 225T650 300V400H0Z"/><path class="terrain terrain-b" d="M0 70Q110 210 205 110T460 125T650 50V0H0Z"/><path class="route-shadow" d="M85 290C130 260 140 310 205 265S242 162 310 180 348 235 405 160 480 108 565 75"/><path class="route-path" d="M85 290C130 260 140 310 205 265S242 162 310 180 348 235 405 160 480 108 565 75"/><g class="route-point" data-route-point="0"><circle cx="85" cy="290" r="19"/><text x="85" y="295">01</text></g><g class="route-point" data-route-point="1"><circle cx="245" cy="203" r="19"/><text x="245" y="208">02</text></g><g class="route-point" data-route-point="2"><circle cx="420" cy="143" r="19"/><text x="420" y="148">03</text></g><g class="route-point" data-route-point="3"><circle cx="565" cy="75" r="19"/><text x="565" y="80">04</text></g></svg>'''
    main=f'''<main id="main">
<section class="campaign-hero"><img class="campaign-landscape" src="{assets}alpine-journey.png" width="1672" height="941" alt="" fetchpriority="high"><div class="campaign-overlay"></div><div class="wrap campaign-layout"><div class="campaign-copy"><span class="eyebrow"><i></i>{E(t['eyebrow'])}</span><h1>{E(m['hero'])}<span>{E(m['accent'])}</span></h1><p>{E(c['intro'])}</p><div class="campaign-actions"><a class="button" href="#tour">{E(m['tour'])}{icon('arrow')}</a><a class="campaign-secondary" href="#early-access">{E(m['early'])} ↗</a></div><div class="hero-capabilities"><span>{icon('planner')}{E(labels['planner'])}</span><span>{icon('navigation')}{E(c['navigation'])}</span><span>{icon('community')}{E(c['community'])}</span></div><small class="campaign-build">{E(c['build'])}</small></div><div class="product-stage">{phone('map',c['map'],'stage-phone',True)}<a class="stage-card stage-card-a" href="#tour"><span class="stage-icon">{icon('planner')}</span><span><small>01 / RAWLO</small><strong>{E(m['plan'])}</strong></span><b>↗</b></a><a class="stage-card stage-card-b" href="#tour" data-tour-start="1"><span class="stage-icon">{icon('navigation')}</span><span><small>02 / RAWLO</small><strong>{E(m['drive'])}</strong></span><b>↗</b></a><span class="stage-orbit orbit-one"></span><span class="stage-orbit orbit-two"></span></div></div><div class="hero-signature wrap"><span>KNOW WHAT’S <b>AHEAD.</b></span><a href="#journey">{E(m['why'])} ↓</a></div></section>
<section class="benefit-intro wrap" id="journey"><span class="kicker">RAWLO / {E(t['nav_features'])}</span><h2>{E(m['why'])}</h2><p>{E(t['hero_sub'])}</p><div class="benefit-strip">{''.join(f'<a href="#tour" data-tour-start="{i}"><span>0{i+1}</span>{icon(name)}<strong>{E(m[key])}</strong><b>↗</b></a>' for i,(name,image,key,body) in enumerate(steps))}</div></section>
<section class="product-tour" id="tour"><div class="wrap"><div class="tour-heading"><div><span class="kicker">RAWLO / {E(m['demolabel'])}</span><h2>{E(m['tourtitle'])}</h2></div><p>{E(c['screens'])}</p></div><div class="tour-tabs" role="tablist" aria-label="{E(m['tour'])}">{tabs}</div><div class="tour-board" id="tour-panel" role="tabpanel" aria-labelledby="tour-tab-0" tabindex="0"><div class="tour-map">{route_art}<div class="tour-map-tag">RAWLO / {E(m['tour'])}</div><div class="tour-caption" aria-live="polite"><span class="tour-count" data-tour-count>01 / 04</span><h3 data-tour-title>{E(m['plan'])}</h3><p data-tour-body>{E(c['planbody'])}</p><a class="text-link" href="#preview" data-tour-gallery data-show-category="planner">{E(t['nav_preview'])} ↗</a></div></div><div class="tour-screen">{phone('itinerary',labels['planner'],'tour-phone')}<span data-tour-label>{E(labels['planner'])}</span></div></div><script type="application/json" id="tour-data">{json.dumps(data,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script></div></section>
<section class="section wrap benefit-mosaic" id="features"><div class="mosaic-heading"><span class="kicker">KNOW WHAT’S AHEAD.</span><h2>{E(t['hero_title'])}</h2></div><div class="mosaic-grid"><article class="mosaic navigation-mosaic" id="navigation"><div class="mosaic-copy"><span class="kicker">{icon('navigation')}{E(c['navigation'])}</span><h3>{E(m['vehicletitle'])}</h3><p>{E(c['navbody'])}</p><a class="text-link" href="#preview" data-show-category="navigation">{E(t['nav_preview'])} ↗</a></div><div class="vehicle-profile"><span>{icon('vehicle')}</span><b>RAWLO</b><i></i>{icon('shield')}</div></article><article class="mosaic planner-mosaic" id="planner"><div class="mosaic-copy"><span class="kicker">{icon('planner')}{E(labels['planner'])}</span><h3>{E(t['share_t'])}</h3><p>{E(c['planbody'])}</p></div><div class="mini-itinerary"><span>01</span><i></i><span>02</span><i></i><span>03</span><i></i>{icon('navigation')}</div></article><article class="mosaic weather-mosaic"><span class="kicker">{icon('weather')} RAWLO</span><h3>{E(t['wx_t'])}</h3><p>{E(t['wx_b'])}</p><div class="weather-symbol">{icon('weather')}</div></article><article class="mosaic map-mosaic" id="map"><div class="mosaic-copy"><span class="kicker">{icon('map')}{E(c['map'])}</span><h3>{E(m['placetitle'])}</h3><p>{E(c['mapbody'])}</p><a class="text-link" href="#preview" data-show-category="map">{E(t['nav_preview'])} ↗</a></div><div class="poi-orbit"><span>{icon('map')}</span><span>{icon('onroad')}</span><span>{icon('mobile')}</span><span>{icon('weather')}</span></div></article></div></section>
<section class="escape-scene"><img src="{assets}coastal-escape.png" width="1672" height="941" alt="" loading="lazy" decoding="async"><div class="wrap escape-copy"><span class="kicker">RAWLO / {E(m['discover'])}</span><h2>{E(m['placetitle'])}</h2><a class="button outline" href="#tour" data-tour-start="2">{E(m['tour'])}{icon('arrow')}</a><span class="escape-signature">KNOW WHAT’S AHEAD.</span></div></section>
<section class="community-story" id="community"><div class="wrap community-layout"><div class="community-story-copy"><span class="kicker">RAWLO / {E(c['community'])}</span><h2>{E(m['communitytitle'])}</h2><p>{E(c['communitybody'])}</p><a class="button outline" href="#preview" data-show-category="community">{E(t['nav_preview'])}{icon('arrow')}</a><div class="community-glyphs">{icon('community')}{icon('map')}{icon('planner')}</div></div><div class="community-showcase">{phone('topics',c['community'],'community-topics')}{phone('community',c['community'],'community-feed')}</div></div></section>
{service_section}
<section class="profile-section wrap" id="profile"><img src="/assets/brand/rawlo_icon.svg" width="76" height="90" alt=""><div><span class="kicker">RAWLO / {E(c['profile'])}</span><h2>{E(c['profile'])}</h2><p>{E(c['profilebody'])}</p></div><a class="text-link" href="#preview" data-show-category="profile">{E(t['nav_preview'])} ↗</a></section>
{country_section}{gallery_section}
<section class="campaign-faq wrap"><span class="kicker">RAWLO / {E(m['faqtitle'])}</span><h2>{E(m['faqtitle'])}</h2><div class="faq-columns"><details><summary>{E(m['faqq'])}</summary><p>{E(c['build'])}. {E(m['early'])}: <a href="{E(mail,quote=True)}">support@rawlo.eu</a>.</p></details><details><summary>{E(c['onroad'])}</summary><p>{E(c['servicebody'])}</p></details></div></section>
<section class="early-access" id="early-access"><div class="wrap access-layout"><div><span class="kicker">RAWLO / iPHONE</span><h2>{E(m['hero'])}<br><span>{E(m['accent'])}</span></h2><p>{E(c['build'])}</p></div><div class="access-action">{button}<small>{E(m['mailnote'])}</small><a class="text-link" href="mailto:support@rawlo.eu">support@rawlo.eu ↗</a></div><span class="access-watermark" aria-hidden="true">RAWLO</span></div></section></main>'''
    document=re.sub(r'<main id="main">.*?</main>',lambda _:main,document,flags=re.S)
    document=document.replace('/assets/styles-v15.css','/assets/styles-v16.css')
    document=document.replace('<script src="/assets/app-v15.js" defer></script>','<script src="/assets/app-v15.js" defer></script><script src="/assets/app-v16.js" defer></script>')
    document=document.replace('<nav class="main-nav" id="main-nav" aria-label="RAWLO">','<nav class="main-nav" id="main-nav" aria-label="RAWLO"><a href="#tour">'+E(m['tour'])+'</a>')
    document=document.replace(f'<a href="#preview" class="button small">{E(t["nav_preview"])}</a>',f'<a href="#early-access" class="button small">{E(m["early"])}</a>')
    return document
